// Example: parent component template with child component
@Component({
  selector: 'app-parent',
  template: '<app-child [value]="parentValue" (valueChange)="onValueChange($event)"></app-child>'
})
export class ParentComponent {
  parentValue = 0;
  onValueChange(newValue: number) {
    this.parentValue = newValue;
  }
}

